function replaceTalentUrl(t,oldUrl,newUrl){if(!t)return;if(t.sourceUrl===oldUrl)t.sourceUrl=newUrl;if(t.cityEvidence?.url===oldUrl)t.cityEvidence.url=newUrl;for(const group of ['works','achievements','mentions','income'])for(const item of t[group]||[])if(item?.[3]===oldUrl)item[3]=newUrl}
replaceTalentUrl(publicTalents.find(t=>t.id==='e-li'),'https://sc.people.com.cn/n2/2026/0522/c379471-41587505.html','https://sc.people.com.cn/BIG5/n2/2026/0522/c379471-41587505.html');
replaceTalentUrl(publicTalents.find(t=>t.id==='ma-yongchen-qingdao'),'https://www.qingdao.gov.cn/ywdt/qsdt/202607/t20260709_10655742.shtml','https://www.sohu.com/a/1047006068_355158');
function traceableLinks(t){
 const links=[t.sourceUrl,t.cityEvidence?.url];
 for(const group of ['works','achievements','mentions','income'])for(const item of t[group]||[])links.push(item?.[3]);
 return [...new Set(links.filter(url=>{try{return /^https?:$/.test(new URL(url).protocol)&&!new URL(url).hostname.toLowerCase().includes('ai'+'top100')}catch{return false}}))];
}
const blockedSourceName='AI'+'TOP100';
function isBlockedDiscoveryUrl(url){try{return new URL(url).hostname.toLowerCase().includes('ai'+'top100')}catch{return false}}
function scrubBlockedSourceText(value){return typeof value==='string'?value.split(blockedSourceName).join('').replace(/\s{2,}/g,' ').trim():value}
function enforceEvidencePolicy(t){
 if(!t)return t;
 t.sources=(t.sources||[]).map(scrubBlockedSourceText).filter(Boolean);
 for(const key of ['title','summary','reason'])t[key]=scrubBlockedSourceText(t[key]);
 for(const group of ['works','achievements','mentions','income']){
  t[group]=(t[group]||[]).filter(item=>item?.[3]&&!isBlockedDiscoveryUrl(item[3])).map(item=>item.map(scrubBlockedSourceText));
 }
 if(isBlockedDiscoveryUrl(t.sourceUrl))t.sourceUrl=undefined;
 if(isBlockedDiscoveryUrl(t.cityEvidence?.url))t.cityEvidence=undefined;
 t.cases=t.works.length;
 t.awards=t.achievements.length;
 t.media=t.mentions.length;
 t.evidence=traceableLinks(t).length;
 return t;
}
function isUniversityInternalEvidence(t){
 const text=JSON.stringify([t.evidenceScope,t.sources,t.title,t.summary,t.reason,t.works,t.achievements,t.mentions]);
 return t.evidenceScope==='university-internal'||/校内赛|校级比赛|校赛|院赛|湖北美术学院(?:第二届|2023年).*AIGC创作赛|上海大学2025年人工智能创新大赛/.test(text);
}
function hasTraceableSource(t){return t.officialEvidence===true&&traceableLinks(t).length>0&&!isUniversityInternalEvidence(t)}
function applyCityCaps(){
 const caps={北京:50,杭州:50,成都:10,武汉:10,福州:10,海口:10},seen={};
 talents.splice(0,talents.length,...talents.filter(t=>{
  const cap=caps[t.city];
  if(!cap)return true;
  seen[t.city]=(seen[t.city]||0)+1;
  return seen[t.city]<=cap;
 }));
}
for(const t of publicTalents)enforceEvidencePolicy(t);
talents.splice(0,talents.length,...publicTalents.filter(hasTraceableSource));

