function go(route,id){state.route=route;state.selected=id||null;location.hash=id?`/${route}/${id}`:`/${route}`;render();scrollTo(0,0)}
function shell(content){return `<div class="app"><header class="topbar"><div class="brand" data-go="home"><img class="brand-logo" src="/assets/ai-zhisheng-logo.png" alt="AI知声"><div class="brand-sub">AI TALENT INDEX</div></div><nav class="nav"><button class="${state.route==='home'?'active':''}" data-go="home">首页</button><button class="${state.route==='search'?'active':''}" data-go="search">全国人才</button><button class="${state.route==='scenarios'?'active':''}" data-go="scenarios">AI场景实验室</button><button class="${state.route==='standards'?'active':''}" data-go="standards">可信标准</button></nav></header>${content}<footer class="footer"><div><b>AI知声 · 全国 AI 人才可信档案库</b><br><small>公开档案与演示档案已分别标注，所有真实信息以原始来源为准。</small></div><small>只呈现公开证据，不提供个人联系方式 · 2026</small></footer></div>`}
function optionSet(value,items){return items.map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}
function availableCities(){const order=['北京','上海','杭州','深圳','广州','成都','南京','济南','武汉','西安','苏州','重庆'];return [...new Set(talents.map(t=>t.city).filter(c=>c&&c!=='未公开'))].sort((a,b)=>{const ai=order.indexOf(a),bi=order.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b,'zh-CN')})}
function categoryControls(prefix='hero'){return `<div class="category-search"><label><span>人才方向</span><select id="${prefix}Category">${optionSet(state.category,['全部方向','AI视频','AIGC创作','AI绘画','AI短剧','Agent','AI产品','OPC'])}</select></label><label><span>可信来源</span><select id="${prefix}Source">${optionSet(state.source,['全部来源','央视/中央媒体','政府/官媒','WaytoAGI','AI春晚','杭州OPC','头部赛事'])}</select></label><label><span>地区</span><select id="${prefix}Region">${optionSet(state.region,['全国',...availableCities(),'地区未公开'])}</select></label></div>`}
function badges(t){return `<div class="proofs"><span class="proof">${t.cases} 商业案例</span><span class="proof">${t.awards} 赛事奖项</span><span class="proof">${t.media} 媒体报道</span></div>`}
function talentCard(t,i){return `<article class="talent-card" data-index="0${i+1}" data-profile="${t.id}"><div class="person-head"><div class="avatar">${t.initial}</div><div><div class="person-name">${t.name}</div><div class="person-title">${t.title} · ${t.city}</div>${t.verified?'<span class="verified">● 本人已认领</span>':''}</div></div><div class="tags">${t.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><p class="card-summary">${t.summary}</p>${badges(t)}<div class="card-foot"><span class="evidence-count">共 ${t.evidence} 项可追溯证据</span><span class="arrow">↗</span></div></article>`}
function home(){return shell(`<main class="page"><section class="hero"><div><div class="eyebrow">CHINA AI TALENT INDEX</div><h1>寻找全国真正<br><span class="brush">做出结果的 AI 人才。</span></h1><p class="lead">从商业案例、赛事公示、央视及各地政府官媒、WaytoAGI、AI春晚与 OPC 社区中，整理每项都能追溯的全国 AI 人才档案。</p></div><aside class="hero-note"><div class="no">全国</div><strong>按能力与证据找人</strong><p>不是粉丝榜，也不是传统简历库。企业看到的是这个人做过什么，以及凭什么值得进一步了解。</p></aside></section><section class="search-stage"><div class="search-label">⌕ 先选分类，再描述你想找的人</div>${categoryControls('hero')}<div class="search-row"><input id="heroQuery" class="search-input" value="${esc(state.query)}" placeholder="例如：做过商业项目、被政府官媒报道的 AI 视频创作者"><button class="btn acid" data-search>搜索全国人才 →</button></div><div class="examples"><button class="example" data-example="有制造业案例的 Agent 开发者">制造业 Agent</button><button class="example" data-example="被央视或官媒报道的 AI 创作者">央视 / 官媒报道</button><button class="example" data-example="获得过头部赛事奖项的 AI 视频创作者">头部赛事获奖者</button></div></section><section class="trust-strip"><div class="trust-item"><div class="trust-num">全国</div><div class="trust-label">覆盖城市与远程人才</div></div><div class="trust-item"><div class="trust-num">${talents.filter(t=>t.real).length}+</div><div class="trust-label">首批真实公开档案</div></div><div class="trust-item"><div class="trust-num">7 类</div><div class="trust-label">社区、赛事与媒体来源</div></div><div class="trust-item"><div class="trust-num">100%</div><div class="trust-label">真实档案附来源依据</div></div></section><div class="demo-note">当前首批库包含真实公开资料档案与少量产品演示档案；人物详情页会明确标识。</div><section><div class="section-head"><h2>全国 AI 人才代表</h2><p>覆盖 AI 视频、视觉、短剧、Agent、产品、工业 AI、健康与机器人等方向。</p></div><div class="talent-grid">${talents.slice(0,12).map(talentCard).join('')}</div><div style="text-align:center;margin-top:26px"><button class="btn dark" data-go="search">查看全部 ${talents.length} 位人才 →</button></div></section><section><div class="section-head"><h2>人才来源分类</h2><p>央视和各级政府官媒是重要来源，但报道只证明公开事实，不代表未来履约保证。</p></div><div class="source-cloud"><button class="source-chip" data-source-search="央视/中央媒体">央视 / 中央媒体</button><button class="source-chip" data-source-search="政府/官媒">各地政府 / 官媒 / 公众号</button><button class="source-chip" data-source-search="WaytoAGI">WaytoAGI</button><button class="source-chip" data-source-search="AI春晚">AI 春晚</button><button class="source-chip" data-source-search="杭州OPC">全国 OPC 社区</button><button class="source-chip" data-source-search="头部赛事">头部赛事获奖者</button></div></section><section class="method"><div class="method-step"><div class="step">STEP 01 / 发现</div><h3>全国公开来源</h3><p>从作者页、作品、比赛、政府官网、官方公众号和权威报道中发现人物。</p></div><div class="method-step"><div class="step">STEP 02 / 核验</div><h3>人物 + 作品 + 角色</h3><p>报道必须明确姓名、AI项目或作品以及人物承担的角色，泛泛提及不收录。</p></div><div class="method-step"><div class="step">STEP 03 / 展示</div><h3>企业快速判断</h3><p>按方向、来源和地区筛选，并展开查看商业案例、奖项与媒体证据。</p></div></section></main>`)}
function sourceMatch(t,s){if(s==='全部来源')return true;const text=t.sources.join('');if(s==='央视/中央媒体')return /央视|人民日报|人民网|新华社|央媒/.test(text);if(s==='政府/官媒')return /政府|杭州网|人民网|人民日报|央视|经信局|官媒|杭州OPC|南京市/.test(text);if(s==='头部赛事')return t.awards>0;return text.replaceAll(' ','').includes(s.replaceAll(' ',''))}
function filtered(){let arr=[...talents];const q=state.query.toLowerCase();if(q)arr=arr.filter(t=>[t.name,...(t.aliases||[]),t.title,t.city,t.summary,...t.tags,...t.sources,t.reason].join(' ').toLowerCase().includes(q)||(/奖项|比赛|赛事/.test(q)&&t.awards)||(/官媒|媒体|报道|央视/.test(q)&&t.media)||(/商业|案例/.test(q)&&t.cases));if(state.category!=='全部方向')arr=arr.filter(t=>t.tags.includes(state.category)||t.title.includes(state.category));if(state.region!=='全国')arr=arr.filter(t=>state.region==='地区未公开'?t.city==='未公开':t.city===state.region);arr=arr.filter(t=>sourceMatch(t,state.source));const selected=[...state.filters],directions=selected.filter(f=>f.startsWith('direction:')).map(f=>f.slice(10)),cities=selected.filter(f=>f.startsWith('city:')).map(f=>f.slice(5));if(directions.length)arr=arr.filter(t=>directions.some(f=>t.tags.includes(f)||t.title.includes(f)));if(cities.length)arr=arr.filter(t=>cities.includes(t.city));if(state.scenarioFilter){const scenario=aiScenarios.find(s=>s.id===state.scenarioFilter);arr=scenario?arr.filter(t=>scenarioTalentScore(t,scenario)>0).sort((a,b)=>scenarioTalentScore(b,scenario)-scenarioTalentScore(a,scenario)):[];}return arr}
function filterOption(value,label,count,prefix=''){const key=`${prefix}${value}`;return `<label class="check"><input type="checkbox" data-filter="${esc(key)}" ${state.filters.has(key)?'checked':''}><span>${label}</span><small>${count}</small></label>`}
function search(){const arr=filtered(),cities=availableCities(),directions=['AIGC创作','AI视频','AI漫剧','AI网站','OPC','数字艺术'].filter(x=>talents.some(t=>t.tags.includes(x)||t.title.includes(x))),countBy=fn=>talents.filter(fn).length;const trustHtml=[['商业案例',t=>t.cases>0],['赛事奖项',t=>t.awards>0],['权威报道',t=>t.media>0],['本人认领',t=>t.verified]].map(([x,fn])=>filterOption(x,x,countBy(fn))).join(''),directionHtml=directions.map(x=>filterOption(x,x,countBy(t=>t.tags.includes(x)||t.title.includes(x)),'direction:')).join(''),cityHtml=cities.map(x=>filterOption(x,x,countBy(t=>t.city===x),'city:')).join('');return shell(`<main class="page"><div class="search-layout"><div class="search-banner category-banner">${categoryControls('list')}<div class="search-row"><input id="listQuery" value="${esc(state.query)}" placeholder="搜索姓名、能力、行业或可信依据"><button class="btn acid" data-list-search>搜索全国人才</button></div></div><aside class="filter"><h3>进一步筛选</h3><div class="filter-group"><div class="filter-title">可信依据</div>${trustHtml}</div><div class="filter-group"><div class="filter-title">能力方向 <em>多选取并集</em></div>${directionHtml}</div><div class="filter-group"><div class="filter-title">城市 <em>多选取并集</em></div>${cityHtml}</div><button class="btn sm" data-clear>清空筛选</button></aside><section><div class="demo-note">筛选项根据已核验人才数据动态生成；括号数字为当前人才库数量。</div><div class="results-top"><b>找到 ${arr.length} 位全国 AI 人才</b><select><option>综合推荐</option><option>商业案例最多</option><option>赛事奖项最多</option><option>证据最近更新</option></select></div><div class="results-list">${arr.length?arr.slice(0,state.limit).map(t=>`<article class="result-card" data-profile="${t.id}"><div class="avatar">${t.initial}</div><div class="result-main"><h3>${t.name} <small>· ${t.city}</small></h3><div>${t.title} ${t.real?'<span class="real-label">真实公开档案</span>':'<span class="demo-label">演示档案</span>'}</div><div class="tags">${t.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="reason"><b>为什么推荐：</b>${t.reason}</div></div><div class="result-proof"><div class="metric"><span>商业 / 产品案例</span><strong>${t.cases}</strong></div><div class="metric"><span>赛事 / 奖项</span><strong>${t.awards}</strong></div><div class="metric"><span>媒体报道</span><strong>${t.media}</strong></div><div class="metric"><span>可追溯证据</span><strong>${t.evidence}</strong></div></div></article>`).join(''):`<div class="empty"><h3>暂时没有完全匹配的人才</h3><p>可以取消部分筛选条件，或切换到全国和全部方向。</p></div>`}</div></section></div></main>`)}
function availableDirections(){const order=['AI视频','AI动画','AI短剧','AI漫剧','商业广告','AI绘画','AI网站','AI产品','Agent','OPC','创作培训'];return order.filter(x=>talents.some(t=>t.tags.includes(x)||t.title.includes(x)))}
function categoryControls(prefix='hero'){return `<div class="category-search"><label><span>人才方向</span><select id="${prefix}Category">${optionSet(state.category,['全部方向',...availableDirections()])}</select></label><label><span>可信来源</span><select id="${prefix}Source">${optionSet(state.source,['全部来源','央视/中央媒体','政府/官媒','WaytoAGI','AI春晚','杭州OPC','头部赛事'])}</select></label><label><span>地区</span><select id="${prefix}Region">${optionSet(state.region,['全国',...availableCities(),'地区未公开'])}</select></label></div>`}
function resultRow(t){return `<article class="result-card" data-profile="${t.id}"><div class="avatar">${t.initial}</div><div class="result-main"><h3>${t.name} <small>· ${t.city}</small></h3><div>${t.title} <span class="real-label">来源已核验</span></div><div class="tags">${t.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="reason"><b>为什么推荐：</b>${t.reason}</div></div><div class="result-proof"><div class="metric"><span>商业 / 产品案例</span><strong>${t.cases}</strong></div><div class="metric"><span>赛事 / 奖项</span><strong>${t.awards}</strong></div><div class="metric"><span>媒体报道</span><strong>${t.media}</strong></div><div class="metric"><span>可追溯证据</span><strong>${t.evidence}</strong></div></div></article>`}
function search(){
 const arr=filtered(),cities=availableCities(),directions=availableDirections(),countBy=fn=>talents.filter(fn).length;
 const trustHtml=`<div class="trust-explainer"><p><b>商业案例</b><span>客户、品牌或项目方公开确认的真实实践。</span></p><p><b>赛事奖项</b><span>面向社会公开赛事的主办方获奖公示。</span></p><p><b>权威报道</b><span>政府、官媒或权威媒体发布的原始报道。</span></p></div>`;
 const directionHtml=directions.map(x=>filterOption(x,x,countBy(t=>t.tags.includes(x)||t.title.includes(x)),'direction:')).join('');
 const cityHtml=cities.map(x=>filterOption(x,x,countBy(t=>t.city===x),'city:')).join('');
 const scenario=state.scenarioFilter?aiScenarios.find(s=>s.id===state.scenarioFilter):null;
 const note=scenario?`当前按「${scenario.industry}」公开证据匹配；仅展示资料中明确出现对应行业经历且能力方向相符的人才。`:'城市根据本人公开资料或地方官媒人物报道判定；能力方向根据公开身份、作品标题与作品简介匹配。';
 return shell(`<main class="page"><div class="search-layout"><div class="search-banner category-banner">${categoryControls('list')}<div class="search-row"><input id="listQuery" value="${esc(state.query)}" placeholder="搜索姓名、能力、行业或可信依据"><button class="btn acid" data-list-search>搜索全国人才</button></div></div><aside class="filter"><h3>进一步筛选</h3><div class="filter-group trust-guide"><div class="filter-title">可信依据说明</div>${trustHtml}</div><div class="filter-group"><div class="filter-title">城市 <em>同组多选取并集</em></div>${cityHtml}</div><div class="filter-group"><div class="filter-title">能力方向 <em>同组多选取并集</em></div>${directionHtml}</div><button class="btn sm" data-clear>清空筛选</button></aside><section><div class="demo-note">${note}</div><div class="results-top"><b>找到 ${arr.length} 位全国 AI 人才</b></div><div class="results-list">${arr.length?arr.slice(0,state.limit).map(resultRow).join(''):`<div class="empty"><h3>暂时没有已核验的匹配人才</h3><p>该场景不会用宽泛标签补足人数；待有可追溯的行业资料后再展示。</p></div>`}</div></section></div></main>`)
}
const scenarioRules={
 food:{capabilities:['AI视频','商业广告','AI产品','Agent'],keywords:['餐饮','餐厅','菜品','菜单','美食','食品','探店','门店']},
 ecommerce:{capabilities:['商业广告','Agent','AI产品','AI视频'],keywords:['电商','商品','SKU','listing','直播','客服','投放','网店','带货']},
 manufacturing:{capabilities:['Agent','AI产品','AI视频'],keywords:['制造','工业','工厂','设备','机器人','生产','工艺','质检','供应链']},
 tourism:{capabilities:['AI视频','AI动画','商业广告','AI产品'],keywords:['文旅','旅游','景区','城市宣传','非遗','博物馆','地标','文化IP','导览']},
 education:{capabilities:['创作培训','Agent','AI产品','AI动画'],keywords:['教育产品','教学','课程','课堂','课件','教师','培训','讲师','教研']},
 retail:{capabilities:['商业广告','Agent','AI产品','AI视频'],keywords:['零售','门店','导购','商超','会员','私域','消费品牌']},
 property:{capabilities:['AI视频','商业广告','Agent','AI产品'],keywords:['地产','房产','楼盘','户型','建筑','样板间','家居','空间设计']},
 health:{capabilities:['Agent','AI产品'],keywords:['医疗','健康','医院','诊疗','药物','医药','康复','生物']},
 finance:{capabilities:['Agent','AI产品'],keywords:['金融','银行','保险','证券','基金','风控','合规','支付']},
 media:{capabilities:['AI短剧','AI漫剧','AI视频','AI动画','商业广告'],keywords:['影像','视频','短剧','漫剧','动画','广告','导演','制片','影视','内容创作']}
};
function scenarioEvidenceText(t){return [t.title,t.summary,t.reason,...(t.works||[]).flat(),...(t.achievements||[]).flat(),...(t.mentions||[]).flat()].filter(x=>typeof x==='string'&&!/^https?:\/\//i.test(x)).join(' ').toLowerCase()}
function scenarioTalentScore(t,s){
 if(!hasTraceableSource(t))return 0;
 if((s.talentIds||[]).includes(t.id))return 1000+(t.cases||0)*2+(t.awards||0)+(t.media||0);
 const rule=scenarioRules[s.id];
 if(!rule)return 0;
 const capabilityHits=rule.capabilities.filter(x=>(t.tags||[]).includes(x)||t.title.includes(x)).length;
 if(!capabilityHits)return 0;
 const text=scenarioEvidenceText(t),keywordHits=rule.keywords.filter(x=>text.includes(x.toLowerCase())).length;
 if(!keywordHits)return 0;
 return capabilityHits*5+Math.min(keywordHits,3)*3+(t.cases>0?2:0)+(t.awards>0?1:0)+(t.media>0?1:0);
}
function scenarioMatchedTalents(s){return talents.filter(t=>scenarioTalentScore(t,s)>0).sort((a,b)=>scenarioTalentScore(b,s)-scenarioTalentScore(a,s))}
function scenarioTalentCount(s){return scenarioMatchedTalents(s).length}
function scenarioTalentAction(s){const count=scenarioTalentCount(s);return count?`<button data-scenario-talent="${s.id}">查看 ${count} 位已核验人才 <b>↗</b></button>`:'<span class="scenario-empty">暂无已核验人才</span>'}
function scenarioLab(){
 const industries=['全部行业',...aiScenarios.map(s=>s.industry)],goals=['全部目标',...new Set(aiScenarios.map(s=>s.goal))];
 const rows=aiScenarios.filter(s=>(state.scenarioIndustry==='全部行业'||s.industry===state.scenarioIndustry)&&(state.scenarioGoal==='全部目标'||s.goal===state.scenarioGoal));
 const chips=industries.map(x=>{const s=aiScenarios.find(item=>item.industry===x),id=s?.id||'all';return `<button class="scenario-chip scenario-chip-${id} ${state.scenarioIndustry===x?'active':''}" data-scenario-industry="${x}"><span>${s?.no||'00'}</span><b>${s?.mark||'全'}</b><em>${x}</em></button>`}).join('');
 return shell(`<main class="scenario-page"><section class="scenario-hero"><div class="scenario-kicker">AI SCENARIO LAB · 01—10</div><div class="scenario-hero-grid"><div><h1>先找场景，<br><span>再找对的人。</span></h1><p>面向企业主的AI应用地图。不是从工具出发，而是从行业问题、业务目标与最小验证项目出发，找到真正具备对应能力的人才。</p></div><aside><strong>10</strong><span>首批垂直行业</span><i></i><strong>40</strong><span>可落地AI场景</span></aside></div></section><section class="scenario-console"><div class="scenario-industries" aria-label="行业筛选">${chips}</div><label class="scenario-goal"><span>企业目标</span><select id="scenarioGoal">${optionSet(state.scenarioGoal,goals)}</select></label></section><section class="scenario-intro"><div><span class="lab-light"></span>SCENARIO INDEX</div><p>当前展示 <b>${rows.length}</b> 个行业方案 · 人数只统计公开资料中能核验对应行业经验的人才</p></section><section class="scenario-grid">${rows.map(s=>`<article class="scenario-card scenario-${s.id}"><header><span class="scenario-no">${s.no}</span><div class="scenario-mark">${s.mark}</div><div><small>${s.goal}</small><h2>${s.industry}</h2></div></header><h3>${s.title}</h3><p class="scenario-pain"><b>业务卡点</b>${s.pain}</p><div class="scenario-list"><b>优先实验场景</b>${s.scenes.map((x,i)=>`<span><i>0${i+1}</i>${x}</span>`).join('')}</div><div class="scenario-start"><b>建议起步</b><p>${s.starter}</p></div><footer><div><small>匹配能力</small><div class="scenario-tags">${s.tags.map(x=>`<span>${x}</span>`).join('')}</div></div>${scenarioTalentAction(s)}</footer></article>`).join('')}</section><section class="lab-method"><div class="lab-method-title"><span>实验方法</span><h2>不先买系统，<br>先跑一个小闭环。</h2></div><ol><li><b>01</b><span>选业务卡点</span><p>选择高频、重复、可衡量的真实任务。</p></li><li><b>02</b><span>定最小实验</span><p>用1–2周和一小批数据验证可行性。</p></li><li><b>03</b><span>匹配人才</span><p>按作品、案例、行业理解和公开证据筛人。</p></li><li><b>04</b><span>量化复盘</span><p>比较时间、成本、质量和业务结果。</p></li></ol></section></main>`)
}
function evidence(items,type){return items.length?items.map(x=>`<article class="evidence-item"><div class="evidence-top"><span class="evidence-type">${type}</span><small>${x[2]}</small></div><h3>${x[0]}</h3><p>${x[1]}</p>${x[3]?`<a class="source-line source-link" href="${esc(x[3])}" target="_blank" rel="noopener noreferrer">↗ 打开原始来源</a>`:'<div class="source-line">来源链接待运营补充</div>'}</article>`).join(''):'<div class="evidence-item"><p>暂未发现可核验记录。</p></div>'}
function profile(){const t=talents.find(x=>x.id===state.selected)||talents[0];const checked=t.sourceAudit?.checkedAt||'2026-08-24';return shell(`<main class="page"><button class="back" data-go="search">← 返回人才列表</button><div class="demo-note">本档案只展示已通过链接可访问性及“姓名 + 作品/身份”内容匹配的公开信息。</div><section class="profile-hero"><div class="profile-title"><div class="eyebrow">SOURCE-AUDITED TALENT DOSSIER · ${t.city}</div><h1>${t.name}</h1><h2>${t.title}</h2><p class="lead">${t.summary}</p><div class="tags">${t.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><aside class="profile-side"><div class="score-label">证据完整度 · 不代表履约保证</div><div class="score-big">${t.score}<span> / 100</span></div><div class="bar"><i style="width:${t.score}%"></i></div><p>已核验 ${t.evidence} 项公开证据，最近复核：${checked}</p></aside></section><section class="profile-grid"><div><div class="dossier"><h2>01 / 商业案例与代表作品</h2>${evidence(t.works,'商业 / 作品')}</div><div class="dossier"><h2>02 / 赛事与奖项</h2>${evidence(t.achievements,'赛事 / 奖项')}</div><div class="dossier"><h2>03 / 政府与权威媒体</h2>${evidence(t.mentions,'媒体报道')}</div><div class="dossier"><h2>04 / 公开收入记录</h2>${evidence(t.income,'收入披露')}<p class="demo-note">收入只按原始来源口径展示，不把公司营收、GMV 或融资额等同于个人收入，也不根据流量估算。</p></div></div><aside><div class="aside-card"><h3>为什么值得关注</h3><p>${t.reason}</p></div><div class="aside-card"><h3>可信依据</h3>${badges(t)}<p>资料来源：${t.sources.join('、')}</p></div><div class="aside-card"><h3>档案时间线</h3><div class="timeline"><div><b>最近复核</b><br><small>${checked}</small></div><div><b>来源状态</b><br><small>链接可访问，姓名与作品/身份匹配</small></div></div></div><div class="aside-card"><h3>档案说明</h3><p>本平台只整理公开事实，不提供个人联系方式，不对未来合作结果作保证。</p><button class="btn sm" data-toast="已进入纠错流程（原型）">纠错 / 申请隐藏</button></div></aside></section></main>`)}
function standards(){return shell(`<main class="page standards-page"><section class="standard-hero"><div class="eyebrow">THE EVIDENCE STANDARD</div><h1>我们如何定义<br><span class="brush">“相对靠谱”。</span></h1><p class="lead">不是平台替人才担保，而是把商业案例、赛事结果、媒体报道和作品署名拆成可点击、可复核的事实，让企业自己判断。</p></section><section class="standard-grid"><article class="standard-card c1"><b>01</b><h2>商业案例</h2><p>优先采信客户官网、品牌官方账号、公开案例页或双方共同确认的交付记录。只有本人单方面描述时，明确标记为“本人声明”。</p><strong>强证据：客户官方案例 / 共同确认</strong></article><article class="standard-card c2"><b>02</b><h2>赛事与奖项</h2><p>必须区分参赛、入围、获奖、评委和导师。只采信面向社会、行业或跨院校公开举办的赛事；大学内部校赛、院赛不作为人才入库依据。</p><strong>强证据：公开赛事主办方获奖公示</strong></article><article class="standard-card c3"><b>03</b><h2>政府与媒体</h2><p>媒体按中央级、省级、市级政府/官媒、权威行业媒体和其他媒体分层。同一通稿被转载多次只算一个原始事实。</p><strong>强证据：原始人物 / 案例报道</strong></article><article class="standard-card c4"><b>04</b><h2>作品与产品</h2><p>核验作品是否上线、人物是否有明确署名、在团队中承担什么角色。无角色说明的团队作品不会直接证明个人能力。</p><strong>强证据：上线作品 / 开源仓库 / 明确署名</strong></article></section><section class="rule-table"><div class="section-head"><h2>证据强弱对照</h2><p>所有结果页上的“为什么推荐”，都必须能回到以下某项证据。</p></div><div class="table-wrap"><table><thead><tr><th>维度</th><th>可作为强证据</th><th>只能作为线索</th></tr></thead><tbody><tr><td>商业案例</td><td>客户官方案例、合同脱敏证明、双方确认</td><td>仅本人称“服务过某品牌”</td></tr><tr><td>赛事奖项</td><td>公开赛事主办方公示、证书核验</td><td>大学内部校赛/院赛、朋友圈截图、非官方海报</td></tr><tr><td>媒体报道</td><td>官媒或权威媒体原始人物报道</td><td>聚合转载、活动通稿点名</td></tr><tr><td>组织身份</td><td>组织官方名单或组织确认</td><td>参加过一次活动</td></tr><tr><td>公开收入</td><td>本人明确披露或可信报道，口径完整</td><td>按流量、GMV、融资额推算</td></tr></tbody></table></div></section><section class="standard-note"><h2>使用提示</h2><p>为便于企业主高效、审慎地了解人才，建议将档案信息作为合作前的公开参考，并结合自身需求进一步核实。</p><div><span><b>隐私与联系</b>档案不展示个人联系方式；如需合作，请通过公开渠道进一步核实与联系。</span><span><b>合作判断</b>平台呈现的是可追溯的公开信息，不构成对未来合作或履约结果的承诺。</span><span><b>自然展示</b>人才按公开信息完整度与匹配度自然呈现，不接受付费调整展示顺序。</span></div></section></main>`)}
